// SIKU — catalogue des composants. Source unique pour la documentation interactive (docs/)
// et la référence des assistants (ai/components.md, généré). Un test vérifie que chaque prop
// listée existe réellement dans le composant, et que chaque composant exporté est catalogué.
//
// p(name, type, default, description)
const p = (name, type, def, desc) => ({ name, type, default: def, desc });

export const groups = [
  { id: 'actions', label: 'Actions' },
  { id: 'forms', label: 'Saisie' },
  { id: 'navigation', label: 'Navigation' },
  { id: 'feedback', label: 'Retours' },
  { id: 'data', label: 'Données' },
  { id: 'game', label: 'Jeu' },
  { id: 'layout', label: 'Structure' },
];

