    props: [p('colors', 'string[]', '—', ''), p('value', 'number', '0', 'bind:value (index).'), p('label', 'string', '—', ''), p('size', "'sm' | 'md'", "'md'", '22 / 28 px'), p('disabled', 'boolean', 'false', ''), p('format', '(index) => string', '« n / total »', 'Compteur et nom accessible de chaque pastille.'), p('onchange', '(index: number) => void', '—', '')],
    controls: [{ prop: 'size', options: ['sm', 'md'] }, { prop: 'disabled', bool: true }],
