    props: [p('image', 'string', '—', 'URL de la planche.'), p('count', 'number', '—', ''), p('columns', 'number', '—', ''), p('value', 'number', '0', 'bind:value (index).'), p('label', 'string', '—', ''), p('size', 'number', '44', 'px'), p('shape', "'round' | 'square'", "'round'", ''), p('disabled', 'boolean', 'false', ''), p('format', '(index) => string', '« n / total »', ''), p('onchange', '(index: number) => void', '—', '')],
